/**
 * @param {string} val
 * @return {Object}
 */
var expect = function(val) {
    return {
        toBe: function(val2) {
            if (val === val2) return true;
            throw new Error('Not Equal');
        },
        notToBe: function(val2) {
            if (val !== val2) return true;
            throw new Error('Equal');
        }
    };
};
